script.setup:
// OpenCV found the edges of the image on this computer (recipe opencv.contours → contours.json);
// the scene draws them as ink lines, longest first.
const data = await (await fetch(ctx.assets["contours.json"])).json();
const gl = ctx.gl;
const makeLines = (data, stride) => {
  const vao = gl.createVertexArray(), buffer = gl.createBuffer();
  gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, stride * 4, 0);
  gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, stride - 2, gl.FLOAT, false, stride * 4, 8);
  gl.bindVertexArray(null);
  return { vao, count: data.length / stride };
};
const segs = [];
data.contours.forEach((line, i) => {
  const order = i / data.contours.length;
  for (let k = 0; k + 3 < line.length; k += 2) segs.push(line[k], line[k + 1], order, line[k + 2], line[k + 3], order);
});
Object.assign(ctx.state, { data, lines: makeLines(new Float32Array(segs), 3), photo: await ctx.utils.loadTexture("great-wave.jpg"),
  p: ctx.utils.createProgram("#version 300 es\nlayout(location=0) in vec2 a_position; layout(location=1) in float a_order;\nuniform vec2 u_fit; out float v_order;\nvoid main(){ v_order = a_order; gl_Position = vec4((a_position * 2.0 - 1.0) * u_fit, 0.0, 1.0); }", "#version 300 es\nprecision highp float; in float v_order; out vec4 outColor; uniform float u_progress; uniform vec3 u_ink;\nvoid main(){ if (v_order > u_progress) discard; float fresh = smoothstep(u_progress - 0.02, u_progress, v_order);\n  outColor = vec4(mix(u_ink, vec3(0.9, 0.3, 0.2), fresh), 1.0); }"), bg: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, "#version 300 es\nprecision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_photo; uniform vec2 u_fit; uniform float u_show; uniform vec3 u_paper;\nvoid main(){ vec2 q = (v_uv - 0.5) / u_fit + 0.5; vec3 c = u_paper;\n  if (all(greaterThanEqual(q, vec2(0.0))) && all(lessThanEqual(q, vec2(1.0)))) c = mix(c, texture(u_photo, q).rgb, u_show);\n  outColor = vec4(c, 1.0); }") });
ctx.publish("contours", data.contours.length);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const img = s.data.width / s.data.height, view = w / h;
const fit = img > view ? [0.92, 0.92 * view / img] : [0.92 * img / view, 0.92];
const cycle = u.u_duration + 2;
const progress = Math.min(1, (ctx.time % cycle) / u.u_duration);
gl.useProgram(s.bg);
ctx.utils.bindTexture(s.bg, "u_photo", s.photo.texture, 0);
ctx.utils.drawFullscreen(s.bg, { u_fit: fit, u_show: u.u_photo });
gl.useProgram(s.p);
ctx.utils.setUniforms(s.p, { u_fit: fit, u_progress: progress, u_ink: u.u_ink });
gl.bindVertexArray(s.lines.vao);
gl.drawArrays(gl.LINES, 0, s.lines.count);
gl.bindVertexArray(null);
